import{a as e,i as t,r as n,t as r}from"./app-Dkwa1Gla.js";var i=JSON.parse(`{"path":"/%E7%AC%AC21%E7%AB%A0%20%E9%A1%B9%E7%9B%AE%E7%AE%A1%E7%90%86%E7%A7%91%E5%AD%A6%E5%9F%BA%E7%A1%80/","title":"第21章 项目管理科学基础","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"第21章 项目管理科学基础/README.md"}`),a={name:`README.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="第21章-项目管理科学基础" tabindex="-1"><a class="header-anchor" href="#第21章-项目管理科学基础"><span>第21章 项目管理科学基础</span></a></h1><h2 id="本章概览" tabindex="-1"><a class="header-anchor" href="#本章概览"><span>本章概览</span></a></h2><p>本章介绍项目管理的科学基础，包括数学基础、经济分析和运筹学的应用。</p><p><strong>重点知识点：</strong></p><ul><li>数学基础</li><li>经济分析方法</li><li>运筹学模型</li><li>决策分析技术</li></ul><hr><h2 id="_21-1-数学基础" tabindex="-1"><a class="header-anchor" href="#_21-1-数学基础"><span>21.1 数学基础</span></a></h2><h3 id="定义" tabindex="-1"><a class="header-anchor" href="#定义"><span>定义</span></a></h3><p>数学基础是指项目管理中使用的数学知识和方法。</p><h3 id="核心内容" tabindex="-1"><a class="header-anchor" href="#核心内容"><span>核心内容</span></a></h3><ul><li>概率论</li><li>统计学</li><li>线性代数</li></ul><h3 id="关键考点" tabindex="-1"><a class="header-anchor" href="#关键考点"><span>关键考点</span></a></h3><ul><li>概率论的应用</li><li>统计学方法</li></ul><h3 id="记忆口诀" tabindex="-1"><a class="header-anchor" href="#记忆口诀"><span>记忆口诀</span></a></h3><p>数学基础很重要，概率统计代数不能少</p><hr><h2 id="_21-2-经济分析" tabindex="-1"><a class="header-anchor" href="#_21-2-经济分析"><span>21.2 经济分析</span></a></h2><h3 id="定义-1" tabindex="-1"><a class="header-anchor" href="#定义-1"><span>定义</span></a></h3><p>经济分析是指对项目进行经济评估的方法。</p><h3 id="核心内容-1" tabindex="-1"><a class="header-anchor" href="#核心内容-1"><span>核心内容</span></a></h3><ul><li>成本效益分析</li><li>投资回报率</li><li>净现值分析</li></ul><h3 id="关键考点-1" tabindex="-1"><a class="header-anchor" href="#关键考点-1"><span>关键考点</span></a></h3><ul><li>经济分析方法</li><li>投资决策指标</li></ul><h3 id="记忆口诀-1" tabindex="-1"><a class="header-anchor" href="#记忆口诀-1"><span>记忆口诀</span></a></h3><p>经济分析看效益，成本回报现值要算好</p><hr><h2 id="_21-3-运筹学" tabindex="-1"><a class="header-anchor" href="#_21-3-运筹学"><span>21.3 运筹学</span></a></h2><h3 id="定义-2" tabindex="-1"><a class="header-anchor" href="#定义-2"><span>定义</span></a></h3><p>运筹学是指运用数学方法优化资源分配的学科。</p><h3 id="核心内容-2" tabindex="-1"><a class="header-anchor" href="#核心内容-2"><span>核心内容</span></a></h3><ul><li>线性规划</li><li>决策树</li><li>排队论</li></ul><h3 id="关键考点-2" tabindex="-1"><a class="header-anchor" href="#关键考点-2"><span>关键考点</span></a></h3><ul><li>运筹学模型</li><li>优化方法</li></ul><h3 id="记忆口诀-2" tabindex="-1"><a class="header-anchor" href="#记忆口诀-2"><span>记忆口诀</span></a></h3><p>运筹学优化资源，线性规划决策树排队论</p>`,35)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};